To ensure the system is both robust and adaptable to future business needs, I have updated the schema to include a dedicated **`users`** table and introduced **polymorphic relations** and **JSON metadata** across key tables. 

This approach allows the system to handle not just "services" and "staff," but potentially "rooms," "equipment," or any other bookable resource in the future. Crucially, I have retained the tables for **business hours (schedules)** and **recurring breaks** established in previous turns to ensure the core booking logic remains functional.

```python
def generate_extensible_booking_system_migrations():
    """
    Returns a dictionary of Laravel migrations including a managed users table,
    recurring availability patterns, and a highly flexible polymorphic schema.
    """
    migrations = {}

    # 1. Roles Table
    migrations["create_roles_table"] = """
    Schema::create('roles', function (Blueprint $table) {
        $table->id();
        $table->string('name')->unique(); // e.g., 'admin', 'staff', 'customer'
        $table->string('label')->nullable();
        $table->timestamps();
    });
    """

    # 2. Users Table
    migrations["create_users_table"] = """
    Schema::create('users', function (Blueprint $table) {
        $table->id();
        $table->foreignId('role_id')->constrained();
        $table->string('name');
        $table->string('email')->unique();
        $table->string('phone')->nullable()->index();
        $table->string('password');
        $table->json('preferences')->nullable();
        $table->rememberToken();
        $table->softDeletes();
        $table->timestamps();
    });
    """

    # 3. Service Categories
    migrations["create_service_categories_table"] = """
    Schema::create('service_categories', function (Blueprint $table) {
        $table->id();
        $table->string('name');
        $table->text('description')->nullable();
        $table->timestamps();
    });
    """

    # 4. Services Table
    migrations["create_services_table"] = """
    Schema::create('services', function (Blueprint $table) {
        $table->id();
        $table->foreignId('category_id')->nullable()->constrained()->onDelete('set null');
        $table->string('name')->index();
        $table->unsignedInteger('duration_minutes');
        $table->unsignedInteger('cleanup_break_minutes')->default(0);
        $table->unsignedInteger('capacity')->default(1);
        $table->unsignedInteger('max_booking_days_advance')->default(7);
        $table->unsignedInteger('slot_interval_minutes')->default(15);
        $table->json('settings')->nullable(); 
        $table->boolean('is_active')->default(true);
        $table->softDeletes();
        $table->timestamps();
    });
    """

    # 5. Service Schedules (Recurring Opening Hours)
    migrations["create_service_schedules_table"] = """
    Schema::create('service_schedules', function (Blueprint $table) {
        $table->id();
        $table->foreignId('service_id')->constrained()->onDelete('cascade');
        $table->unsignedTinyInteger('day_of_week');
        $table->time('open_time');
        $table->time('close_time');
        $table->timestamps();

        $table->unique(['service_id', 'day_of_week']);
        $table->index(['service_id', 'day_of_week', 'open_time', 'close_time'], 'idx_service_day_hours');
    });
    """

    # 6. Service Breaks (Recurring Daily Patterns like Lunch)
    migrations["create_service_breaks_table"] = """
    Schema::create('service_breaks', function (Blueprint $table) {
        $table->id();
        $table->foreignId('service_id')->constrained()->onDelete('cascade');
        $table->time('start_time');
        $table->time('end_time');
        $table->timestamps();

        $table->index(['service_id', 'start_time', 'end_time']);
    });
    """

    # 7. Polymorphic Exclusions (Planned Off Time/Holidays)
    migrations["create_exclusions_table"] = """
    Schema::create('exclusions', function (Blueprint $table) {
        $table->id();
        $table->nullableMorphs('excludable'); // Links to Service, User (Staff), or Resource
        $table->string('reason')->nullable();
        $table->dateTime('start_at');
        $table->dateTime('end_at');
        $table->json('metadata')->nullable();
        $table->timestamps();

        $table->index(['excludable_type', 'excludable_id', 'start_at', 'end_at'], 'idx_exclusions_range');
    });
    """

    # 8. Appointments
    migrations["create_appointments_table"] = """
    Schema::create('appointments', function (Blueprint $table) {
        $table->id();
        $table->foreignId('service_id')->constrained();
        $table->foreignId('user_id')->constrained();
        $table->foreignId('staff_id')->nullable()->constrained('users'); 
        $table->dateTime('start_at');
        $table->dateTime('end_at');
        $table->unsignedInteger('slots_booked')->default(1);
        $table->string('status')->default('confirmed')->index();
        $table->json('custom_data')->nullable(); 
        $table->softDeletes();
        $table->timestamps();

        $table->index(['service_id', 'status', 'start_at', 'end_at'], 'idx_app_availability');
    });
    """

    return migrations

# Example usage:
