### 2. The Python Application (`app.py`)

This version integrates the HTML form with the security measures (hashing and validation) and the AWS RDS connection logic.

```python
import os
import re
from flask import Flask, render_template, request
import mysql.connector
from mysql.connector import Error
from werkzeug.security import generate_password_hash
from dotenv import load_dotenv

load_dotenv()

app = Flask(__name__)
app.secret_key = os.getenv('FLASK_SECRET', 'default_secret_key')

def get_db_connection():
    try:
        return mysql.connector.connect(
            host=os.getenv('DB_HOST'),
            user=os.getenv('DB_USER'),
            password=os.getenv('DB_PASS'),
            database=os.getenv('DB_NAME')
        )
    except Error as e:
        print(f"Database Connection Error: {e}")
        return None

def validate_input(name, email, phone, password):
    if not all([name, email, phone, password]):
        return False, "All fields are required."
    if not re.match(r"[^@]+@[^@]+\.[^@]+", email):
        return False, "Invalid email format."
    if not phone.isdigit() or len(phone) < 10:
        return False, "Phone number must be at least 10 digits."
    if len(password) < 8:
        return False, "Password must be at least 8 characters long."
    return True, ""

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/submit', methods=['POST'])
def submit():
    if request.method == 'POST':
        # Retrieve data using names from HTML
        name = request.form.get('name')
        email = request.form.get('email')
        phone = request.form.get('phone')
        password = request.form.get('password')

        # 1. Validation
        is_valid, error_msg = validate_input(name, email, phone, password)
        if not is_valid:
            return f"<h1>Validation Error</h1><p>{error_msg}</p><a href='/'>Go Back</a>"

        # 2. Security (Password Hashing)
        hashed_pw = generate_password_hash(password)

        # 3. Save to AWS RDS
        conn = get_db_connection()
        if conn:
            try:
                cursor = conn.cursor()
                sql = "INSERT INTO students (name, email, phone, password) VALUES (%s, %s, %s, %s)"
                cursor.execute(sql, (name, email, phone, hashed_pw))
                conn.commit()
                cursor.close()
                conn.close()
                return f"<h1>Success!</h1><p>Data for {name} saved securely to AWS.</p><a href='/'>Back to Form</a>"
            except Error as e:
                return f"<h1>Database Error</h1><p>{str(e)}</p>"
        else:
            return "<h1>Connection Error</h1><p>Could not connect to AWS RDS.</p>"

if __name__ == '__main__':
    app.run(debug=True)
```

### Key Integration Points:

1.  **Action & Method:** The HTML `<form action="/submit" method="POST">` matches the `@app.route('/submit', methods=['POST'])` in Python.
2.  **Data Extraction:** `request.form.get('email')` in Python retrieves the value from `<input name="email">` in the HTML.
